//! Support code for wrappers generated by `gufo-kernel-build`. Hand-written
//! code calls the generated wrappers, never these helpers.

use gufo_formats::GgmlType;

use crate::error::{HipError, LaunchError};
use crate::memory::{
    Derivation, DeviceSlice, DeviceSliceMut, IndexSlice, IndexSliceMut, IndexSpec, QuantSlice,
};
use crate::stream::Stream;

pub use crate::record::Arg;

/// Status struct returned by every generated `extern "C"` shim.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct RawLaunchResult {
    pub status: i32,
    pub hip_error: i32,
}

const OK: i32 = 0;
const UNSUPPORTED: i32 = 1;
const HIP_ERROR: i32 = 2;

/// Result of a launcher that may reject a geometry. `Unsupported` means no
/// work was enqueued and the caller must take its documented fallback.
#[must_use]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Launch {
    Launched,
    Unsupported,
}

pub fn begin(stream: &Stream) -> Result<(), LaunchError> {
    Ok(stream.ensure_healthy()?)
}

/// Reports a checked launch to the stream's recorder. `Ok(None)`: launch
/// now. `Ok(Some(result))`: graph validation; do not launch, return `result`.
pub fn record(
    stream: &Stream,
    launcher: &'static str,
    args: &[Arg<'_>],
) -> Result<Option<Launch>, LaunchError> {
    stream
        .with_recorder(|recorder| recorder.record(launcher, args))
        .unwrap_or(Ok(None))
}

pub fn add(a: usize, b: usize, param: &'static str) -> Result<usize, LaunchError> {
    a.checked_add(b)
        .ok_or(LaunchError::ExtentOverflow { param })
}

pub fn sub(a: usize, b: usize, param: &'static str) -> Result<usize, LaunchError> {
    a.checked_sub(b)
        .ok_or(LaunchError::ExtentOverflow { param })
}

pub fn mul(a: usize, b: usize, param: &'static str) -> Result<usize, LaunchError> {
    a.checked_mul(b)
        .ok_or(LaunchError::ExtentOverflow { param })
}

pub fn div(a: usize, b: usize, param: &'static str) -> Result<usize, LaunchError> {
    a.checked_div(b)
        .ok_or(LaunchError::ExtentOverflow { param })
}

fn require(
    param: &'static str,
    home: Option<u64>,
    stream: &Stream,
    actual: usize,
    required: usize,
) -> Result<(), LaunchError> {
    if home.is_some_and(|home| home != stream.id()) {
        return Err(LaunchError::ForeignStream { param });
    }
    if actual < required {
        return Err(LaunchError::ExtentTooShort {
            param,
            required,
            actual,
        });
    }
    Ok(())
}

/// Read-only arguments: buffers of `stream` or immutable tensors.
pub fn require_in<T>(
    stream: &Stream,
    param: &'static str,
    slice: &DeviceSlice<'_, T>,
    required: usize,
) -> Result<(), LaunchError> {
    require(param, slice.home_stream(), stream, slice.len(), required)
}

/// Written arguments: buffers of `stream` only.
pub fn require_out<T>(
    stream: &Stream,
    param: &'static str,
    slice: &DeviceSliceMut<'_, T>,
    required: usize,
) -> Result<(), LaunchError> {
    require(
        param,
        Some(slice.home_stream()),
        stream,
        slice.len(),
        required,
    )
}

/// Index arguments: like `require_in`, and every value must lie below `limit`.
pub fn require_indices(
    stream: &Stream,
    param: &'static str,
    indices: &IndexSlice<'_>,
    required: usize,
    limit: usize,
) -> Result<(), LaunchError> {
    require_index_spec(
        stream,
        param,
        indices,
        required,
        limit,
        u32::MAX,
        false,
        false,
    )
}

/// Index arguments whose kernel bounds only `value & mask`, skips the
/// padding value when `padded`, and reads `int32` values when `signed`.
#[allow(clippy::too_many_arguments)]
pub fn require_index_spec(
    stream: &Stream,
    param: &'static str,
    indices: &IndexSlice<'_>,
    required: usize,
    limit: usize,
    mask: u32,
    padded: bool,
    signed: bool,
) -> Result<(), LaunchError> {
    require_in(stream, param, &indices.values(), required)?;
    check_spec(param, indices.spec(), mask, padded)?;
    if signed && !indices.spec().fits_i32() {
        return Err(LaunchError::IndexSpec {
            param,
            reason: "indices of an int32 kernel must fit a non-negative i32",
        });
    }
    let bound = indices.bound();
    if usize::try_from(bound).map_or(true, |bound| bound > limit) {
        return Err(LaunchError::IndexBound {
            param,
            bound,
            limit,
        });
    }
    Ok(())
}

/// The buffer's mask must be the kernel's, and padding needs a kernel that
/// skips it.
fn check_spec(
    param: &'static str,
    spec: IndexSpec,
    mask: u32,
    padded: bool,
) -> Result<(), LaunchError> {
    if spec.mask != mask {
        return Err(LaunchError::IndexSpec {
            param,
            reason: "index mask differs from the kernel's",
        });
    }
    if spec.padded && !padded {
        return Err(LaunchError::IndexSpec {
            param,
            reason: "padded indices for a kernel that does not skip padding",
        });
    }
    Ok(())
}

/// Kernel-written indices: the kernel writes `required` values that satisfy
/// `value & mask < below` (or padding when `padded`), which the buffer's
/// spec must admit. A `signed` kernel writes `int32` values.
#[allow(clippy::too_many_arguments)]
pub fn require_indices_out(
    stream: &Stream,
    param: &'static str,
    indices: &IndexSliceMut<'_>,
    required: usize,
    below: usize,
    mask: u32,
    padded: bool,
    signed: bool,
) -> Result<(), LaunchError> {
    require(
        param,
        Some(indices.home_stream()),
        stream,
        indices.len(),
        required,
    )?;
    let spec = indices.spec();
    if spec.mask != mask {
        return Err(LaunchError::IndexSpec {
            param,
            reason: "index mask differs from the kernel's",
        });
    }
    if padded && !spec.padded {
        return Err(LaunchError::IndexSpec {
            param,
            reason: "the kernel writes padding into unpadded indices",
        });
    }
    if usize::try_from(spec.bound).is_ok_and(|bound| below > bound) {
        return Err(LaunchError::IndexBound {
            param,
            bound: spec.bound,
            limit: below,
        });
    }
    // Non-negative int32 values need an unmasked bound within i32.
    if (signed || spec.signed) && (mask != u32::MAX || below > 1 << 31) {
        return Err(LaunchError::IndexSpec {
            param,
            reason: "the kernel's values may not fit a non-negative i32",
        });
    }
    Ok(())
}

/// Marks kernel-written indices as rewritten by the launch about to run,
/// derived from `derived` or from nothing.
///
/// # Safety
/// Only the generated wrapper of a launcher whose kernel writes `indices`
/// in this launch, computed from exactly the indices `derived` names, may
/// call this: consumers trust the recorded derivation.
#[doc(hidden)]
pub unsafe fn commit(indices: &mut IndexSliceMut<'_>, derived: Option<Derivation>) {
    indices.commit(derived);
}

/// Indices a kernel may use only together with `source`: they must have been
/// computed from its current generation with the same geometry `tag`.
pub fn require_derived(
    param: &'static str,
    indices: &IndexSlice<'_>,
    source_name: &'static str,
    source: &IndexSlice<'_>,
    tag: u64,
) -> Result<(), LaunchError> {
    if indices.derived() != Some(source.derivation(tag)) {
        return Err(LaunchError::Provenance {
            param,
            source: source_name,
        });
    }
    Ok(())
}

/// Quantized arguments: `rows` rows of `cols` values in the slice's format,
/// with `cols` a whole number of format blocks, followed by `tail` bytes the
/// kernel may read past the last row.
pub fn require_quant(
    stream: &Stream,
    param: &'static str,
    weights: &QuantSlice<'_>,
    rows: usize,
    cols: usize,
    tail: usize,
) -> Result<(), LaunchError> {
    let row_bytes =
        weights
            .format()
            .encoded_bytes(cols as u64)
            .ok_or(LaunchError::InvalidArgument {
                param,
                reason: "columns are not a whole number of format blocks",
            })?;
    let required = usize::try_from(row_bytes)
        .ok()
        .and_then(|b| b.checked_mul(rows))
        .and_then(|b| b.checked_add(tail))
        .ok_or(LaunchError::ExtentOverflow { param })?;
    require_in(stream, param, &weights.bytes(), required)
}

/// Paired weights the kernel decodes with one format.
pub fn require_same_format(
    param: &'static str,
    weights: &QuantSlice<'_>,
    other_name: &'static str,
    other: &QuantSlice<'_>,
) -> Result<(), LaunchError> {
    let _ = other_name;
    if weights.format() == other.format() {
        Ok(())
    } else {
        Err(LaunchError::InvalidArgument {
            param,
            reason: "storage format differs from the paired weights",
        })
    }
}

/// Quantized arguments whose format the launcher supports.
pub fn require_format(
    param: &'static str,
    weights: &QuantSlice<'_>,
    allowed: &[GgmlType],
) -> Result<(), LaunchError> {
    if allowed.contains(&weights.format()) {
        Ok(())
    } else {
        Err(LaunchError::InvalidArgument {
            param,
            reason: "storage format not supported by this launcher",
        })
    }
}

/// A `requires` relation of the kernel contract.
pub fn precondition(
    holds: bool,
    launcher: &'static str,
    requirement: &'static str,
) -> Result<(), LaunchError> {
    if holds {
        Ok(())
    } else {
        Err(LaunchError::Precondition {
            launcher,
            requirement,
        })
    }
}

pub fn rem(a: usize, b: usize, param: &'static str) -> Result<usize, LaunchError> {
    a.checked_rem(b)
        .ok_or(LaunchError::ExtentOverflow { param })
}

pub fn finish(
    stream: &Stream,
    raw: RawLaunchResult,
    launcher: &'static str,
) -> Result<Launch, LaunchError> {
    let result = match raw.status {
        OK => Launch::Launched,
        UNSUPPORTED => Launch::Unsupported,
        HIP_ERROR => {
            let error = HipError::new(raw.hip_error, launcher);
            let _ = stream.observe::<()>(Err(error));
            return Err(LaunchError::Hip(error));
        }
        _ => return Err(LaunchError::LauncherException { launcher }),
    };
    stream.with_recorder(|recorder| recorder.set_result(result));
    Ok(result)
}

pub fn finish_void(
    stream: &Stream,
    raw: RawLaunchResult,
    launcher: &'static str,
) -> Result<(), LaunchError> {
    finish(stream, raw, launcher).map(|_| ())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn extent_arithmetic_reports_overflow_with_the_parameter() {
        assert_eq!(mul(3, 4, "x"), Ok(12));
        assert_eq!(
            mul(usize::MAX, 2, "cache"),
            Err(LaunchError::ExtentOverflow { param: "cache" })
        );
        assert_eq!(
            sub(1, 2, "tail"),
            Err(LaunchError::ExtentOverflow { param: "tail" })
        );
        assert_eq!(
            div(1, 0, "rows"),
            Err(LaunchError::ExtentOverflow { param: "rows" })
        );
    }
}

#[cfg(all(test, feature = "gpu"))]
#[allow(clippy::unwrap_used)]
mod gpu_tests {
    use super::*;
    use crate::memory::IndexSpec;

    #[test]
    fn derived_indices_belong_to_one_source_view_and_generation() {
        let stream = Stream::new().unwrap();
        let mut ids = stream.alloc_indices(8, 4).unwrap();
        stream.upload_indices(&[3; 8], &mut ids).unwrap();
        let mut counts = stream.alloc_indices_with(8, IndexSpec::below(9)).unwrap();
        // What a generated wrapper does for `indices_out` with `derived_from`
        // after its kernel wrote the first four counts from ids[0..6].
        let from = ids.slice(0..6).derivation(4);
        // SAFETY: the test stands in for such a launch; the counts are only
        // compared, never passed to a kernel.
        unsafe { commit(&mut counts.slice_mut(0..4), Some(from)) };
        assert_eq!(counts.derived(), Some(from));
        require_derived("counts", &counts.slice(0..4), "ids", &ids.slice(0..6), 4).unwrap();

        // Another source view, geometry or counts range does not match.
        let mismatch =
            |r: Result<(), LaunchError>| matches!(r, Err(LaunchError::Provenance { .. }));
        assert!(mismatch(require_derived(
            "counts",
            &counts.slice(0..4),
            "ids",
            &ids.slice(0..8),
            4
        )));
        assert!(mismatch(require_derived(
            "counts",
            &counts.slice(0..4),
            "ids",
            &ids.slice(2..8),
            4
        )));
        assert!(mismatch(require_derived(
            "counts",
            &counts.slice(0..4),
            "ids",
            &ids.slice(0..6),
            5
        )));
        assert!(mismatch(require_derived(
            "counts",
            &counts.slice(0..8),
            "ids",
            &ids.slice(0..6),
            4
        )));

        // Rewriting the source invalidates the derivation, and rewriting the
        // counts drops it.
        stream.upload_indices(&[1], &mut ids).unwrap();
        assert!(mismatch(require_derived(
            "counts",
            &counts.slice(0..4),
            "ids",
            &ids.slice(0..6),
            4
        )));
        stream.upload_indices(&[0], &mut counts).unwrap();
        assert_eq!(counts.derived(), None);
    }
}
